UPDATE businesses SET description = 'Pistorius Scheepers Attorneys Inc, founded in 2019, operates from Persequor Technopark at 5 De Havilland Crescent in Pretoria as what the firm describes as a dynamic and progressive legal practice serving clients both locally and internationally. The firm''s practice areas span property law, labour law, family law, general litigation and dispute resolution, debt collection, commercial and corporate law, legal cost consulting services, and deceased estates, trusts and fiduciary services, along with correspondent instructions for other firms. Its stated vision is to become a trusted leader in the legal profession, setting standards for excellence, integrity and innovation, while its mission centres on delivering legal services with professionalism and precision tailored to each client''s circumstances. Since its establishment, the firm has grown into what it describes as a highly regarded legal practice, built around protecting client rights, resolving disputes and providing strategic legal guidance across its range of practice areas.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://ps-law.co.za/', '$[#]', 'https://ps-law.co.za/about-us/'), description_enriched_at = datetime('now') WHERE slug = 'pistorius-scheepers-attorneys-val-de-grace' AND description = 'Pistorius Scheepers Attorneys is a Pretoria law firm founded in 2019, specializing in commercial and corporate law, family law, general litigation and dispute resolution, debt collection, and deceased estates.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
